inline constexpr const char* BVHBUILDER_BVHINTERNAL_COMP =
    "/**\n"
    " * @file bvhInternal.comp\n"
    " * @brief Compute shader for constructing the internal nodes of a BVH tree using Morton codes.\n"
    " */\n"
    "\n"
    "#version 450\n"
    "\n"
    "layout(local_size_x = 256) in;\n"
    "\n"
    "/**\n"
    " * @brief Uniform buffer containing global information for BVH construction.\n"
    " */\n"
    "layout(binding = 0) uniform BvhGlobal {\n"
    "    uint nElements; // Total number of elements\n"
    "} u_bvhGlobal; // BVH global information buffer\n"
    "\n"
    "/**\n"
    " * @brief Storage buffer for storing the input Morton codes for each triangle.\n"
    " */\n"
    "layout(binding = 8) readonly buffer MortonsIn {\n"
    "    uint codes[]; // Array of Morton codes corresponding to the triangle indices\n"
    "} b_mortonsIn; // Morton codes input buffer\n"
    "\n"
    "/**\n"
    " * @brief Struct representing a node in the BVH tree.\n"
    " */\n"
    "struct BvhNode {\n"
    "    int idxLeft; // Index of the left child node\n"
    "    int idxRight; // Index of the right child node\n"
    "    int idxParent; // Index of the parent node\n"
    "    int idxElement; // Index of the element for leaf nodes\n"
    "\n"
    "    vec4 aabbMin; // Minimum corner of the axis-aligned bounding box (AABB) for the node\n"
    "    vec4 aabbMax; // Maximum corner of the axis-aligned bounding box (AABB) for the node\n"
    "};\n"
    "/**\n"
    " * @brief Storage buffer for storing the BVH nodes of the tree.\n"
    " */\n"
    "layout(binding = 13) buffer BvhNodes {\n"
    "    BvhNode nodes[]; // Array of BVH nodes representing the internal structure of the BVH tree\n"
    "} b_bvhNodes; // BVH nodes buffer\n"
    "\n"
    "/**\n"
    " * @brief Function to compute the longest common prefix (LCP) between two Morton codes.\n"
    " * @param i Index of the first Morton code.\n"
    " * @param j Index of the second Morton code.\n"
    " * @param N Total number of triangles (size of the Morton codes array).\n"
    " * @return Length of the longest common prefix between two Morton codes, or -1 if invalid indices.\n"
    " */\n"
    "int lcp(int i, int j, uint N) {\n"
    "    if (i == j)\n"
    "        return 32;\n"
    "    if (j < 0 || j >= int(N))\n"
    "        return -1;\n"
    "\n"
    "    uint a = b_mortonsIn.codes[i];\n"
    "    uint b = b_mortonsIn.codes[j];\n"
    "    uint diff = a ^ b;\n"
    "\n"
    "    if (diff != 0)\n"
    "        return 31 - int(findMSB(diff));\n"
    "    uint idxDiff = uint(i ^ j);\n"
    "    return 32 + (31 - int(findMSB(idxDiff)));\n"
    "}\n"
    "\n"
    "void main() {\n"
    "    int i = int(gl_GlobalInvocationID.x);\n"
    "    int N = int(u_bvhGlobal.nElements);\n"
    "\n"
    "    if (i == 0)\n"
    "        b_bvhNodes.nodes[0].idxParent = -1;\n"
    "\n"
    "    if (i >= N - 1)\n"
    "        return;\n"
    "\n"
    "    // ----------------------------------\n"
    "    // Step 1: determine direction\n"
    "    // ----------------------------------\n"
    "\n"
    "    int lcpL = lcp(i, i - 1, N);\n"
    "    int lcpR = lcp(i, i + 1, N);\n"
    "\n"
    "    int d = (lcpR > lcpL) ? 1 : -1;\n"
    "\n"
    "    int deltaMin = min(lcpL, lcpR);\n"
    "\n"
    "    // ----------------------------------\n"
    "    // Step 2: find range (exponential + binary search)\n"
    "    // ----------------------------------\n"
    "\n"
    "    int lmax = 2;\n"
    "    while (lcp(i, i + lmax * d, N) > deltaMin)\n"
    "        lmax *= 2;\n"
    "\n"
    "    int l = 0;\n"
    "    for (int t = lmax / 2; t > 0; t /= 2) {\n"
    "        if (lcp(i, i + (l + t) * d, N) > deltaMin)\n"
    "            l += t;\n"
    "    }\n"
    "\n"
    "    int j = i + l * d;\n"
    "\n"
    "    int first = min(i, j);\n"
    "    int last  = max(i, j);\n"
    "\n"
    "    // ----------------------------------\n"
    "    // Step 3: find split\n"
    "    // ----------------------------------\n"
    "\n"
    "    int deltaNode = lcp(first, last, N);\n"
    "\n"
    "    int split = first;\n"
    "    int stride = last - first;\n"
    "\n"
    "    do {\n"
    "        stride = (stride + 1) >> 1;\n"
    "        int mid = split + stride;\n"
    "        if (mid < last) {\n"
    "            if (lcp(first, mid, N) > deltaNode)\n"
    "                split = mid;\n"
    "        }\n"
    "    } while (stride > 1);\n"
    "\n"
    "    // ----------------------------------\n"
    "    // Step 4: assign children\n"
    "    // ----------------------------------\n"
    "\n"
    "    int leftChild = 0, rightChild = 0;\n"
    "\n"
    "    if (split == first)\n"
    "        leftChild = split + (N - 1); // leaf\n"
    "    else\n"
    "        leftChild = split;\n"
    "\n"
    "    if (split + 1 == last)\n"
    "        rightChild = split + 1 + (N - 1); // leaf\n"
    "    else\n"
    "        rightChild = split + 1;\n"
    "\n"
    "    // write node\n"
    "    b_bvhNodes.nodes[i].idxLeft = leftChild;\n"
    "    b_bvhNodes.nodes[i].idxRight = rightChild;\n"
    "    b_bvhNodes.nodes[i].idxElement = -1; // internal node\n"
    "\n"
    "    // set parent\n"
    "    b_bvhNodes.nodes[leftChild].idxParent = i;\n"
    "    b_bvhNodes.nodes[rightChild].idxParent = i;\n"
    "}\n"
    "";

