inline constexpr const char* BVHBUILDER_RADIXHIST_COMP =
    "/**\n"
    " * @file radixHist.comp\n"
    " * @brief Compute shader for building the histogram of Morton codes.\n"
    " */\n"
    "\n"
    "#version 450\n"
    "\n"
    "layout(local_size_x = 256) in;\n"
    "\n"
    "/**\n"
    " * @brief Uniform buffer containing global information for BVH construction.\n"
    " */\n"
    "layout(binding = 0) uniform BvhGlobal {\n"
    "    uint nElements; // Total number of elements\n"
    "} u_bvhGlobal; // BVH global information buffer\n"
    "\n"
    "/**\n"
    " * @brief Uniform buffer containing information about the current radix pass.\n"
    " */\n"
    "layout(binding = 4) uniform RadixInfo {\n"
    "    uint shift; // Number of bits to shift for the current radix pass\n"
    "} u_radixInfo; // Radix information buffer\n"
    "\n"
    "/**\n"
    " * @brief Storage buffer for storing the input Morton codes for each triangle.\n"
    " */\n"
    "layout(binding = 6) readonly buffer MortonsIn {\n"
    "    uint codes[]; // Array of Morton codes corresponding to the triangle indices\n"
    "} b_mortonsIn; // Morton codes input buffer\n"
    "\n"
    "/**\n"
    " * @brief Storage buffer for storing the histogram bins.\n"
    " */\n"
    "layout(binding = 9) buffer Histogram {\n"
    "    uint bins[]; // Array of histogram bins\n"
    "} b_histogram; // Histogram buffer\n"
    "\n"
    "shared uint s_localHist[64]; // Shared array for storing the local histogram for each workgroup\n"
    "\n"
    "void main() {\n"
    "    uint lid = gl_LocalInvocationID.x;\n"
    "    uint gid = gl_GlobalInvocationID.x;\n"
    "    uint group = gl_WorkGroupID.x;\n"
    "\n"
    "    // Initialize the local histogram bins to zero for the current workgroup.\n"
    "    // Each workgroup will compute a histogram for its portion of the data.\n"
    "    if (lid < 64)\n"
    "        s_localHist[lid] = 0;\n"
    "    barrier();\n"
    "\n"
    "    // Each thread processes one element and updates the local histogram based on the Morton code.\n"
    "    if (gid < u_bvhGlobal.nElements) {\n"
    "        uint key = b_mortonsIn.codes[gid];\n"
    "        uint bucket = (key >> u_radixInfo.shift) & 63;\n"
    "        atomicAdd(s_localHist[bucket], 1);\n"
    "    }\n"
    "    barrier();\n"
    "\n"
    "    // After all threads in the workgroup have updated the local histogram,\n"
    "    // the first 64 threads write the results to the global histogram buffer.\n"
    "    if (lid < 64) {\n"
    "        uint index = group * 64 + lid;\n"
    "        b_histogram.bins[index] = s_localHist[lid];\n"
    "    }\n"
    "}\n"
    "";

