    "/**\n"
    " * @file radixScatt.comp\n"
    " * @brief Compute shader for scattering Morton codes into buckets based on current radix pass.\n"
    " */\n"
    "\n"
    "#version 450\n"
    "\n"
    "layout(local_size_x = 256) in;\n"
    "\n"
    "/**\n"
    " * @brief Uniform buffer containing global information for BVH construction.\n"
    " */\n"
    "layout(binding = 0) uniform BvhGlobal {\n"
    "    uint nElements; // Total number of elements\n"
    "} u_bvhGlobal; // BVH global information buffer\n"
    "\n"
    "/**\n"
    " * @brief Uniform buffer containing information about the current radix pass.\n"
    " */\n"
    "layout(binding = 4) uniform RadixInfo {\n"
    "    uint shift; // Number of bits to shift for the current radix pass\n"
    "} u_radixInfo; // Radix information buffer\n"
    "\n"
    "/**\n"
    " * @brief Storage buffer for storing the input elements indices.\n"
    " */\n"
    "layout(binding = 5) readonly buffer IndicesIn {\n"
    "    uint indices[]; // Array of elements indices\n"
    "} b_indicesIn; // Elements indices input buffer\n"
    "/**\n"
    " * @brief Storage buffer for storing the input Morton codes for each elements.\n"
    " */\n"
    "layout(binding = 6) readonly buffer MortonsIn {\n"
    "    uint codes[]; // Array of Morton codes corresponding to the elements indices\n"
    "} b_mortonsIn; // Morton codes input buffer\n"
    "/**\n"
    " * @brief Storage buffer for storing the output elements indices after scattering.\n"
    " */\n"
    "layout(binding = 7) buffer IndicesOut {\n"
    "    uint indices[]; // Array of elements indices after scattering\n"
    "} b_indicesOut; // Elements indices output buffer\n"
    "/**\n"
    " * @brief Storage buffer for storing the output Morton codes after scattering.\n"
    " */\n"
    "layout(binding = 8) buffer MortonsOut {\n"
    "    uint codes[]; // Array of Morton codes after scattering\n"
    "} b_mortonsOut; // Morton codes output buffer\n"
    "\n"
    "/**\n"
    " * @brief Storage buffer for storing the histogram bins.\n"
    " */\n"
    "layout(binding = 9) buffer Histogram {\n"
    "    uint bins[]; // Array of histogram bins\n"
    "} b_histogram; // Histogram buffer\n"
    "\n"
    "/**\n"
    " * @brief Storage buffer for storing the base offsets for each bucket in the histogram.\n"
    " */\n"
    "layout(binding = 10) buffer BucketBase {\n"
    "    uint base[64]; // Array of base offsets for each bucket\n"
    "} b_bucketBase; // Bucket base buffer\n"
    "\n"
    "/**\n"
    " * @brief Storage buffer for storing the offsets for each bucket in the histogram.\n"
    " */\n"
    "layout(binding = 11) buffer Offsets {\n"
    "    uint offsets[]; // Array of offsets for each bucket\n"
    "} b_offsets; // Offsets buffer\n"
    "\n"
    "shared uint s_localHist[64]; // Shared array for storing the local histogram\n"
    "shared uint s_blockOffset[64]; // Shared array for storing the block offsets for each bucket\n"
    "shared uint s_offsets[64]; // Shared array for storing the offsets from the global offsets buffer\n"
    "\n"
    "void main() {\n"
    "    uint lid = gl_LocalInvocationID.x;\n"
    "    uint gid = gl_GlobalInvocationID.x;\n"
    "    uint block = gl_WorkGroupID.x;\n"
    "\n"
    "    // The first 64 threads in each workgroup load the histogram bins and offsets\n"
    "    // for their block into shared memory.\n"
    "    if (lid < 64) {\n"
    "        uint idx = block * 64 + lid;\n"
    "        s_localHist[lid] = b_histogram.bins[idx];\n"
    "        s_offsets[lid] = b_offsets.offsets[idx];\n"
    "    }\n"
    "    barrier();\n"
    "\n"
    "    // The first thread in the workgroup computes the block offsets for each bucket\n"
    "    // based on the local histogram.\n"
    "    if (lid == 0) {\n"
    "        uint sum = 0;\n"
    "        for (uint b = 0; b < 64; ++b) {\n"
    "            s_blockOffset[b] = sum;\n"
    "            sum += s_localHist[b];\n"
    "        }\n"
    "    }\n"
    "    barrier();\n"
    "\n"
    "    if (gid >= u_bvhGlobal.nElements)\n"
    "        return;\n"
    "\n"
    "    // Each thread processes one element and scatters it to the correct position\n"
    "    // in the output buffer.\n"
    "    uint idxTri = b_indicesIn.indices[gid];\n"
    "    uint code = b_mortonsIn.codes[gid];\n"
    "\n"
    "    uint bucket = (code >> u_radixInfo.shift) & 63;\n"
    "    uint bucketBase = b_bucketBase.base[bucket];\n"
    "    uint offset = s_offsets[bucket];\n"
    "    uint index = bucketBase + offset + atomicAdd(s_blockOffset[bucket], 1);\n"
    "\n"
    "    b_mortonsOut.codes[index] = code;\n"
    "    b_indicesOut.indices[index] = idxTri;\n"
    "}\n"
    "";

