/**
 * @brief Retrieve the shader string by name.
 * @param name The name of the shader file.
 * @return The shader source code as a string, or an empty string if not found.
 */
inline std::string get(const std::string& name) {
    static const auto map = std::unordered_map<std::string, std::string> {
        { "bvhBuilder/bound.comp", BVHBUILDER_BOUND_COMP },
        { "bvhBuilder/bvhAABB.comp", BVHBUILDER_BVHAABB_COMP },
        { "bvhBuilder/bvhInternal.comp", BVHBUILDER_BVHINTERNAL_COMP },
        { "bvhBuilder/bvhLeafBLAS.comp", BVHBUILDER_BVHLEAFBLAS_COMP },
        { "bvhBuilder/bvhLeafTLAS.comp", BVHBUILDER_BVHLEAFTLAS_COMP },
        { "bvhBuilder/mortonBLAS.comp", BVHBUILDER_MORTONBLAS_COMP },
        { "bvhBuilder/mortonTLAS.comp", BVHBUILDER_MORTONTLAS_COMP },
        { "bvhBuilder/radixBucket.comp", BVHBUILDER_RADIXBUCKET_COMP },
        { "bvhBuilder/radixHist.comp", BVHBUILDER_RADIXHIST_COMP },
        { "bvhBuilder/radixPrefix.comp", BVHBUILDER_RADIXPREFIX_COMP },
        { "bvhBuilder/radixScatt.comp", BVHBUILDER_RADIXSCATT_COMP },
        { "pathTracer.comp", PATHTRACER_COMP },
        { "preview.frag", PREVIEW_FRAG },
        { "preview.vert", PREVIEW_VERT },
        { "quad.frag", QUAD_FRAG },
        { "quad.vert", QUAD_VERT },
    };
    if (auto it = map.find(name); it != map.end())
        return it->second;
    return {};
}

